    q("[data-ds-close]").addEventListener("click",close);q("[data-ds-collapse]").addEventListener("click",()=>{const collapsed=q("[data-ds-controls]").classList.toggle("is-collapsed");q(".deep-space-shell").classList.toggle("is-controls-collapsed",collapsed);translate();viewer.resize();viewer.scene.requestRender();});
    overlay.querySelectorAll("[data-mode]").forEach((b)=>b.addEventListener("click",()=>{mode=b.dataset.mode;if(scaleContext==="nearby")enterNearby(nearbyTier);else if(scaleContext==="milky-way")enterMilkyWay();else if(scaleContext==="local-group")enterLocalGroup();else if(scaleContext==="galaxy-groups")enterGalaxyGroups({selectedId:phase4Selected?.id});else if(scaleContext==="virgo")enterVirgo({selectedId:phase4Selected?.id});else if(scaleContext==="laniakea")enterLaniakea({selectedId:phase4Selected?.id});else if(scaleContext==="cosmic-web")enterCosmicWeb({selectedId:phase4Selected?.id});else if(scaleContext==="observable-universe")enterObservableUniverse({selectedId:phase4Selected?.id});else{renderAll();if(smallBodySelected||selected!=="sun")focusSelectedObject();else setCamera("inclined");}}));
